'use client'

import { useState, useTransition } from 'react'
import { toggleNotificationPreference } from './actions'

export default function Home() {
  const [isEnabled, setIsEnabled] = useState(false)
  const [isPending, startTransition] = useTransition()

  const handleToggle = () => {
    startTransition(async () => {
      await toggleNotificationPreference('user-1', isEnabled)
      setIsEnabled(!isEnabled)
    })
  }

  return (
    <main>
      <h1>Settings</h1>
      <p>Notification Preference</p>
      <button
        onClick={handleToggle}
        disabled={isPending}
        style={{
          padding: '0.5rem 1rem',
          backgroundColor: isEnabled ? '#22c55e' : '#6b7280',
          color: 'white',
          border: 'none',
          borderRadius: '0.375rem',
          cursor: isPending ? 'wait' : 'pointer',
          opacity: isPending ? 0.7 : 1,
        }}
      >
        {isPending ? 'Updating...' : isEnabled ? 'Notifications On' : 'Notifications Off'}
      </button>
    </main>
  )
}

